WITH RankedInvoices AS (
    SELECT *,
           ROW_NUMBER() OVER (
               PARTITION BY id ,docnumber
               ORDER BY loaddate DESC
           ) AS rn
    FROM stg.[Invoice(IES)]
)
DELETE FROM RankedInvoices
WHERE rn > 1;

 WITH RankedInvoicesline AS (
    SELECT *,
           ROW_NUMBER() OVER (
               PARTITION BY id ,[Line_Id]
               ORDER BY loaddate DESC
           ) AS rn
    FROM [Stg].[Invoice_Sales_Item_Line(IES)]
)
DELETE FROM RankedInvoicesline
WHERE rn > 1;
